/**
 * @param {number[]} rec1
 * @param {number[]} rec2
 * @return {boolean}
 */
var isRectangleOverlap = function(rec1, rec2) {
    const innerSquareBottomX = Math.max(rec1[0], rec2[0]);
    const innerSquareBottomY = Math.max(rec1[1], rec2[1]);
    const innerSquareTopX = Math.min(rec1[2], rec2[2]);
    const innerSquareTopY = Math.min(rec1[3], rec2[3]);

    return innerSquareTopX - innerSquareBottomX > 0 &&
        innerSquareTopY - innerSquareBottomY > 0;
};
